import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;
    static final long[] INV = new long[65];

    static {
        INV[1] = 1;
        for (int i = 2; i < INV.length; i++) {
            INV[i] = MOD - (MOD / i) * INV[(int) (MOD % i)] % MOD;
        }
    }

    static long expectedFactor(long prime, int exponent, int k) {
        long[] dp = new long[exponent + 1];
        long[] next = new long[exponent + 1];
        dp[exponent] = 1;

        for (int step = 0; step < k; step++) {
            long suffix = 0;
            for (int j = exponent; j >= 0; j--) {
                suffix = (suffix + dp[j] * INV[j + 1]) % MOD;
                next[j] = suffix;
            }
            long[] temp = dp;
            dp = next;
            next = temp;
        }

        long result = 0;
        long power = 1;
        long p = prime % MOD;

        for (int j = 0; j <= exponent; j++) {
            result = (result + dp[j] * power) % MOD;
            power = power * p % MOD;
        }
        return result;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long n = fs.nextLong();
        int k = fs.nextInt();

        long remaining = n;
        long answer = 1;

        int count = 0;
        while ((remaining & 1L) == 0) {
            remaining >>= 1;
            count++;
        }
        if (count > 0) {
            answer = answer * expectedFactor(2, count, k) % MOD;
        }

        count = 0;
        while (remaining % 3 == 0) {
            remaining /= 3;
            count++;
        }
        if (count > 0) {
            answer = answer * expectedFactor(3, count, k) % MOD;
        }

        long divisor = 5;
        long increment = 2;
        while (divisor * divisor <= remaining) {
            count = 0;
            while (remaining % divisor == 0) {
                remaining /= divisor;
                count++;
            }
            if (count > 0) {
                answer = answer * expectedFactor(divisor, count, k) % MOD;
            }
            divisor += increment;
            increment = 6 - increment;
        }

        if (remaining > 1) {
            answer = answer * expectedFactor(remaining, 1, k) % MOD;
        }

        System.out.println(answer);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0;
        private int length = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) return -1;
            }
            return buffer[pointer++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            long value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

